#!/usr/bin/env python3
"""
enhance_snake.py
Post-processes the SVG files generated by Platane/snk to add:
- Month labels (Nov, Dec, Jan, Feb, Mar, Apr, May, Jun, Jul, Aug, Sep, Oct, Nov)
- Day labels (Mon, Wed, Fri)
- Crisp calendar cell border styling (--cb) so empty cells are clearly visible
- Contribution level legend (Less [0][1][2][3][4] More)
"""

import re
import os

def enhance_svg(filepath, is_dark=True):
    if not os.path.exists(filepath):
        print(f"File not found: {filepath}")
        return

    with open(filepath, 'r', encoding='utf-8') as f:
        svg = f.read()

    # Avoid duplicate enhancement
    if 'class="lbl-d"' in svg:
        print(f"Already enhanced: {filepath}")
        return

    # 1. Update root <svg> tag ONLY
    svg_tag_match = re.search(r'<svg[^>]+>', svg)
    if svg_tag_match:
        old_tag = svg_tag_match.group(0)
        new_tag = re.sub(r'viewBox="[^"]+"', 'viewBox="-38 -32 902 195"', old_tag)
        new_tag = re.sub(r'width="[^"]+"', 'width="902"', new_tag)
        new_tag = re.sub(r'height="[^"]+"', 'height="195"', new_tag)
        svg = svg.replace(old_tag, new_tag, 1)

    # 2. Styling adjustments
    if is_dark:
        cb = '#272e38'  # Crisp visible border for empty cells in dark mode
        lbl_color = '#7d8590'  # GitHub dark secondary text
        c0, c1, c2, c3, c4 = '#161b22', '#01311f', '#034525', '#0f6d31', '#00c647'
    else:
        cb = '#d0d7de'  # GitHub light border
        lbl_color = '#656d76'  # GitHub light secondary text
        c0, c1, c2, c3, c4 = '#ebedf0', '#9be9a8', '#40c463', '#30a14e', '#216e39'

    # Update cell border in styles
    svg = svg.replace('--cb:#1b1f230a;', f'--cb:{cb};')

    # Add text styles to <style>
    font_stack = '-apple-system,BlinkMacSystemFont,\\"Segoe UI\\",\\"Noto Sans\\",Helvetica,Arial,sans-serif'
    extra_styles = (
        f'.lbl{{font-family:{font_stack};font-size:10px;fill:{lbl_color};text-anchor:start}}'
        f'.lbl-d{{font-family:{font_stack};font-size:9px;fill:{lbl_color};text-anchor:start}}'
        f'.lgd{{font-family:{font_stack};font-size:10px;fill:{lbl_color}}}'
    )
    svg = svg.replace('</style>', extra_styles + '</style>')

    # 3. Month labels (Nov 2025 to Nov 2026 across 53 columns)
    months = [
        ('Nov', 2), ('Dec', 50), ('Jan', 114), ('Feb', 178), ('Mar', 242),
        ('Apr', 322), ('May', 386), ('Jun', 450), ('Jul', 514), ('Aug', 578),
        ('Sep', 658), ('Oct', 722), ('Nov', 802)
    ]
    month_tags = ''.join([f'<text x="{x}" y="-10">{m}</text>' for m, x in months])
    month_group = f'<g class="lbl">{month_tags}</g>'

    # 4. Day labels (Mon at y=27, Wed at y=59, Fri at y=91)
    day_group = (
        f'<g class="lbl-d">'
        f'<text x="-32" y="27">Mon</text>'
        f'<text x="-32" y="59">Wed</text>'
        f'<text x="-32" y="91">Fri</text>'
        f'</g>'
    )

    # 5. Legend at bottom right (Less [ ] [ ] [ ] [ ] [ ] More)
    legend_group = (
        f'<g class="lgd">'
        f'<text x="710" y="126">Less</text>'
        f'<rect x="738" y="116" width="10" height="10" rx="2" ry="2" fill="{c0}" stroke="{cb}" stroke-width="1"/>'
        f'<rect x="752" y="116" width="10" height="10" rx="2" ry="2" fill="{c1}" stroke="{cb}" stroke-width="1"/>'
        f'<rect x="766" y="116" width="10" height="10" rx="2" ry="2" fill="{c2}" stroke="{cb}" stroke-width="1"/>'
        f'<rect x="780" y="116" width="10" height="10" rx="2" ry="2" fill="{c3}" stroke="{cb}" stroke-width="1"/>'
        f'<rect x="794" y="116" width="10" height="10" rx="2" ry="2" fill="{c4}" stroke="{cb}" stroke-width="1"/>'
        f'<text x="810" y="126">More</text>'
        f'</g>'
    )

    # Insert groups right before </svg>
    svg = svg.replace('</svg>', f'{month_group}{day_group}{legend_group}</svg>')

    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(svg)

    print(f"Enhanced {filepath} successfully.")

if __name__ == '__main__':
    enhance_svg('images/github-snake-dark.svg', is_dark=True)
    enhance_svg('images/github-snake.svg', is_dark=False)
